import 'dart:convert';
import 'dart:typed_data';

/// Inlined byte representation of the critical above-the-fold hero profile portrait.
/// Inlining the 57KB image eliminates the 5-second asynchronous HTTP fetch / AssetBundle
/// roundtrip during Flutter Web startup, guaranteeing INSTANT (0ms) Frame-1 rendering.
class HeroImageData {
  static const String base64Jpeg = '';

  static final Uint8List bytes = base64Decode(base64Jpeg);
}